def generate_balanced_sequences(n, s):
    a = []
    b = []
    balance_a = 0
    balance_b = 0

    for i in range(n):
        if s[i] == '1':
            a.append('(')
            b.append('(')
            balance_a += 1
            balance_b += 1
        else:
            if balance_a < n // 2:
                a.append('(')
                balance_a += 1
            else:
                a.append(')')
            if balance_b < n // 2:
                b.append('(')
                balance_b += 1
            else:
                b.append(')')

    return ''.join(a), ''.join(b)

def main():
    t = int(input())
    results = []

    for _ in range(t):
        n = int(input())
        s = input()

        try:
            a, b = generate_balanced_sequences(n, s)
            results.append("YES")
            results.append(a)
            results.append(b)
        except:
            results.append("NO")

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
